'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import { motion, AnimatePresence } from 'framer-motion';
import dynamic from 'next/dynamic';
import { CategoryPanel } from '@/components/studio/CategoryPanel';
import { PropertyPanel } from '@/components/studio/PropertyPanel';
import { Navbar } from '@/components/layout/Navbar';
import { Button } from '@/components/ui/Button';
import { useDesignStore } from '@/lib/store';
import { Save, Eye, ArrowLeft, RotateCcw, Plus, X, SlidersHorizontal } from 'lucide-react';
import Link from 'next/link';

// Dynamically import Scene3D with SSR disabled
const Scene3D = dynamic(() => import('@/components/3d/Scene3D').then(mod => mod.Scene3D), {
  ssr: false,
  loading: () => (
    <div className="w-full h-full bg-gradient-to-b from-gray-900 to-gray-800 flex items-center justify-center">
      <div className="text-white/60 text-sm">Loading 3D Studio...</div>
    </div>
  ),
});

export default function StudioPage() {
  const router = useRouter();
  const { currentDesign, saveDesign, resetScene } = useDesignStore();
  const [showMobilePanel, setShowMobilePanel] = useState<'none' | 'add' | 'properties'>('none');

  useEffect(() => {
    console.log('[DEBUG] StudioPage - currentDesign:', currentDesign);
    if (!currentDesign) {
      console.log('[DEBUG] StudioPage - No currentDesign, redirecting to templates');
      router.push('/templates');
    }
  }, [currentDesign, router]);

  if (!currentDesign) {
    console.log('[DEBUG] StudioPage - Rendering null (no currentDesign)');
    return null;
  }
  console.log('[DEBUG] StudioPage - Rendering with currentDesign:', currentDesign.id, currentDesign.name);

  const handleSave = () => {
    saveDesign();
  };

  const handleReset = () => {
    if (confirm('Reset your design? This will clear all objects.')) {
      resetScene();
    }
  };

  return (
    <div className="h-screen flex flex-col bg-[#F7F7F5]">
      <Navbar />
      
      {/* Studio Header */}
      <div className="pt-16 lg:pt-20 bg-white border-b border-[#E5E5E8] shrink-0">
        <div className="px-4 sm:px-6 lg:px-8 py-3 lg:py-4 flex items-center justify-between">
          <div className="flex items-center gap-3 lg:gap-4 min-w-0">
            <Link href="/templates">
              <Button variant="ghost" size="sm" className="text-[#5A5A5F] hover:text-[#111111] shrink-0">
                <ArrowLeft className="w-4 h-4 lg:mr-2" />
                <span className="hidden lg:inline">Exit</span>
              </Button>
            </Link>
            <div className="h-6 w-px bg-[#E5E5E8] hidden lg:block" />
            <div className="min-w-0">
              <h1 className="text-sm lg:text-lg font-semibold text-[#111111] truncate">{currentDesign.name}</h1>
              <p className="text-xs text-[#8C8C92] hidden sm:block">
                {currentDesign.objects.length} objects
              </p>
            </div>
          </div>
          
          <div className="flex items-center gap-1.5 lg:gap-2 shrink-0">
            <Button 
              variant="ghost" 
              size="sm" 
              onClick={handleReset}
              className="text-[#8C8C92] hover:text-red-500 hidden sm:flex"
            >
              <RotateCcw className="w-4 h-4 mr-2" />
              Reset
            </Button>
            <Button 
              variant="outline" 
              size="sm" 
              onClick={handleSave}
              className="border-[#E5E5E8] hidden sm:flex"
            >
              <Save className="w-4 h-4 mr-2" />
              Save
            </Button>
            <Link href="/preview">
              <Button size="sm" className="bg-[#C6A85C] hover:bg-[#E0C878] text-[#111111]">
                <Eye className="w-4 h-4 lg:mr-2" />
                <span className="hidden lg:inline">Preview</span>
              </Button>
            </Link>
          </div>
        </div>
      </div>

      {/* Studio Layout */}
      <div className="flex-1 flex overflow-hidden relative">
        {/* Left Panel - Categories (Desktop) */}
        <div className="hidden lg:block w-72 bg-white border-r border-[#E5E5E8] overflow-y-auto">
          <CategoryPanel onClose={() => {}} />
        </div>

        {/* Center - 3D Scene */}
        <div className="flex-1 relative bg-[#F0EFE9]">
          <Scene3D />
          
          {/* Quick Tips */}
          <div className="absolute top-4 left-4 z-10 hidden sm:block">
            <div className="bg-white/90 backdrop-blur-sm rounded-xl px-4 py-2 text-xs text-[#8C8C92] border border-[#E5E5E8] shadow-sm">
              <span className="text-[#C6A85C] font-medium">Tip:</span> Click objects to select • Drag to move
            </div>
          </div>

          {/* Mobile: Compact top bar for object count */}
          <div className="lg:hidden absolute top-4 left-4 right-4 z-10 pointer-events-none">
            <div className="bg-white/90 backdrop-blur-sm rounded-xl px-3 py-2 text-xs text-[#8C8C92] border border-[#E5E5E8] shadow-sm inline-block pointer-events-auto">
              {currentDesign.objects.length} objects
            </div>
          </div>
        </div>

        {/* Right Panel - Properties (Desktop) */}
        <div className="hidden lg:block w-80 bg-white border-l border-[#E5E5E8] overflow-y-auto">
          <PropertyPanel />
        </div>

        {/* Mobile Bottom Toolbar */}
        <div className="lg:hidden absolute bottom-0 left-0 right-0 z-20">
          {/* Backdrop when panel is open */}
          <AnimatePresence>
            {showMobilePanel !== 'none' && (
              <motion.div
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                className="absolute inset-0 bg-black/20 -top-[100vh]"
                onClick={() => setShowMobilePanel('none')}
              />
            )}
          </AnimatePresence>

          {/* Slide-up Panel */}
          <AnimatePresence>
            {showMobilePanel === 'add' && (
              <motion.div
                initial={{ y: '100%' }}
                animate={{ y: 0 }}
                exit={{ y: '100%' }}
                transition={{ type: 'spring', damping: 25, stiffness: 200 }}
                className="bg-white rounded-t-3xl shadow-2xl border-t border-[#E5E5E8] max-h-[70vh] flex flex-col"
              >
                <div className="flex items-center justify-between p-4 border-b border-[#E5E5E8]">
                  <h3 className="font-semibold text-[#111111]">Add Elements</h3>
                  <button 
                    onClick={() => setShowMobilePanel('none')}
                    className="p-2 hover:bg-[#F7F7F5] rounded-full"
                  >
                    <X className="w-5 h-5 text-[#5A5A5F]" />
                  </button>
                </div>
                <div className="flex-1 overflow-y-auto p-4">
                  <CategoryPanel onClose={() => setShowMobilePanel('none')} />
                </div>
              </motion.div>
            )}
          </AnimatePresence>

          <AnimatePresence>
            {showMobilePanel === 'properties' && (
              <motion.div
                initial={{ y: '100%' }}
                animate={{ y: 0 }}
                exit={{ y: '100%' }}
                transition={{ type: 'spring', damping: 25, stiffness: 200 }}
                className="bg-white rounded-t-3xl shadow-2xl border-t border-[#E5E5E8] max-h-[70vh] flex flex-col"
              >
                <div className="flex items-center justify-between p-4 border-b border-[#E5E5E8]">
                  <h3 className="font-semibold text-[#111111]">Properties</h3>
                  <button 
                    onClick={() => setShowMobilePanel('none')}
                    className="p-2 hover:bg-[#F7F7F5] rounded-full"
                  >
                    <X className="w-5 h-5 text-[#5A5A5F]" />
                  </button>
                </div>
                <div className="flex-1 overflow-y-auto p-4">
                  <PropertyPanel />
                </div>
              </motion.div>
            )}
          </AnimatePresence>

          {/* Bottom Action Bar */}
          <div className="bg-white border-t border-[#E5E5E8] px-4 py-3 safe-area-pb">
            <div className="flex items-center justify-between">
              {/* Add Button */}
              <button
                onClick={() => setShowMobilePanel(showMobilePanel === 'add' ? 'none' : 'add')}
                className={`flex items-center gap-2 px-4 py-2.5 rounded-xl font-medium transition-colors ${
                  showMobilePanel === 'add'
                    ? 'bg-[#C6A85C] text-[#111111]'
                    : 'bg-[#F7F7F5] text-[#5A5A5F] hover:bg-[#EFEFF2]'
                }`}
              >
                <Plus className="w-5 h-5" />
                <span className="text-sm">Add</span>
              </button>

              {/* Quick Actions */}
              <div className="flex items-center gap-2">
                <button
                  onClick={handleSave}
                  className="p-2.5 bg-[#F7F7F5] hover:bg-[#EFEFF2] rounded-xl text-[#5A5A5F]"
                >
                  <Save className="w-5 h-5" />
                </button>
                <button
                  onClick={() => setShowMobilePanel(showMobilePanel === 'properties' ? 'none' : 'properties')}
                  className={`p-2.5 rounded-xl transition-colors ${
                    showMobilePanel === 'properties'
                      ? 'bg-[#C6A85C] text-[#111111]'
                      : 'bg-[#F7F7F5] text-[#5A5A5F] hover:bg-[#EFEFF2]'
                  }`}
                >
                  <SlidersHorizontal className="w-5 h-5" />
                </button>
                <Link href="/preview">
                  <button className="p-2.5 bg-[#C6A85C] hover:bg-[#E0C878] rounded-xl text-[#111111]">
                    <Eye className="w-5 h-5" />
                  </button>
                </Link>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
