'use client';

import { motion, AnimatePresence } from 'framer-motion';
import { useState } from 'react';
import { useDesignStore } from '@/lib/store';
import type { ObjectCategory, ObjectType } from '@/lib/types';
import { 
  Circle, 
  Armchair,
  ImageIcon, 
  CircleDot, 
  Lightbulb, 
  Type, 
  Flower2,
  ChevronRight,
  Plus,
  Box
} from 'lucide-react';

const categories: { id: ObjectCategory; label: string; icon: React.ReactNode; objects: { type: ObjectType; label: string }[] }[] = [
  {
    id: 'tables',
    label: 'Tables',
    icon: <Circle className="w-5 h-5" />,
    objects: [
      { type: 'round-table', label: 'Round Table' },
      { type: 'rect-table', label: 'Rectangle Table' },
    ],
  },
  {
    id: 'chairs',
    label: 'Chairs',
    icon: <Armchair className="w-5 h-5" />,
    objects: [
      { type: 'chair', label: 'Banquet Chair' },
    ],
  },
  {
    id: 'backdrops',
    label: 'Backdrops',
    icon: <ImageIcon className="w-5 h-5" />,
    objects: [
      { type: 'backdrop', label: 'Backdrop' },
    ],
  },
  {
    id: 'balloons',
    label: 'Balloons',
    icon: <CircleDot className="w-5 h-5" />,
    objects: [
      { type: 'balloon-arch', label: 'Balloon Arch' },
      { type: 'balloon-column', label: 'Balloon Column' },
    ],
  },
  {
    id: 'lighting',
    label: 'Lighting',
    icon: <Lightbulb className="w-5 h-5" />,
    objects: [
      { type: 'spotlight', label: 'Spotlight' },
      { type: 'uplight', label: 'Uplight' },
    ],
  },
  {
    id: 'signage',
    label: 'Signage',
    icon: <Type className="w-5 h-5" />,
    objects: [
      { type: 'signage', label: 'Welcome Sign' },
    ],
  },
  {
    id: 'centerpieces',
    label: 'Centerpieces',
    icon: <Flower2 className="w-5 h-5" />,
    objects: [
      { type: 'centerpiece', label: 'Centerpiece' },
    ],
  },
];

interface CategoryPanelProps {
  onClose?: () => void;
}

export function CategoryPanel({ onClose }: CategoryPanelProps) {
  const [expandedCategory, setExpandedCategory] = useState<string | null>('tables');
  const { addObject, cameraPosition } = useDesignStore();

  const handleAddObject = (type: ObjectType, category: ObjectCategory) => {
    // Spawn at camera position (center of view) with fallback
    const spawnPoint = cameraPosition || { x: 0, z: 0 };
    addObject(type, category, spawnPoint);
    onClose?.();
  };

  return (
    <div className="h-full flex flex-col">
      <div className="p-4 lg:p-5 border-b border-[#E5E5E8]">
        <div className="flex items-center gap-2 text-[#111111] font-semibold">
          <Box className="w-5 h-5 text-[#C6A85C]" />
          <span>Add Elements</span>
        </div>
        <p className="text-xs text-[#8C8C92] mt-1">Click to add to your scene</p>
      </div>
      
      <div className="flex-1 overflow-y-auto p-2 space-y-1">
        {categories.map((category) => (
          <div key={category.id}>
            <motion.button
              onClick={() => setExpandedCategory(
                expandedCategory === category.id ? null : category.id
              )}
              className={`
                w-full flex items-center justify-between p-3 rounded-xl transition-all duration-200
                ${expandedCategory === category.id 
                  ? 'bg-[#C6A85C]/10 text-[#111111]' 
                  : 'hover:bg-[#F7F7F5] text-[#5A5A5F]'
                }
              `}
            >
              <div className="flex items-center gap-3">
                <span className={expandedCategory === category.id ? 'text-[#C6A85C]' : 'text-[#8C8C92]'}>
                  {category.icon}
                </span>
                <span className="font-medium text-sm">{category.label}</span>
              </div>
              <motion.div
                animate={{ rotate: expandedCategory === category.id ? 90 : 0 }}
                className="text-[#8C8C92]"
              >
                <ChevronRight className="w-4 h-4" />
              </motion.div>
            </motion.button>
            
            <AnimatePresence>
              {expandedCategory === category.id && (
                <motion.div
                  initial={{ height: 0, opacity: 0 }}
                  animate={{ height: 'auto', opacity: 1 }}
                  exit={{ height: 0, opacity: 0 }}
                  className="overflow-hidden"
                >
                  <div className="pl-10 pr-2 py-2 space-y-1">
                    {category.objects.map((obj) => (
                      <motion.button
                        key={obj.type}
                        whileHover={{ scale: 1.02 }}
                        whileTap={{ scale: 0.98 }}
                        onClick={() => handleAddObject(obj.type, category.id)}
                        className="w-full flex items-center gap-2 text-left px-3 py-2.5 rounded-lg text-sm text-[#5A5A5F] hover:bg-[#F7F7F5] hover:text-[#111111] transition-colors"
                      >
                        <Plus className="w-3.5 h-3.5 text-[#C6A85C]" />
                        {obj.label}
                      </motion.button>
                    ))}
                  </div>
                </motion.div>
              )}
            </AnimatePresence>
          </div>
        ))}
      </div>
    </div>
  );
}
